-- STEP12: use existing delivery desk scope on legacy cancellation, dispatch, documentation, workflow and change routes.
CREATE OR REPLACE FUNCTION public.ff27_document_invoice(p_branch uuid, p_number text, p_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;v_existing text;v_stage text;v_invoiced timestamptz;v_ref text:=pg_catalog.btrim(COALESCE(p_ref,''));
BEGIN
 IF auth.uid() IS NULL
   OR NOT public.ff49_can_work_branch(p_branch,ARRAY['manager','cashier'])
   OR NOT public.ff38_permission_allowed(auth.uid(),'edit_order')
 THEN RAISE EXCEPTION 'ليس لديك صلاحية توثيق الفاتورة' USING ERRCODE='42501'; END IF;
 IF p_number IS NULL OR p_number !~ '^[0-9]{1,18}$' OR pg_catalog.length(v_ref) NOT BETWEEN 1 AND 80 THEN
  RAISE EXCEPTION 'رقم الطلب أو مرجع الفاتورة غير صحيح';
 END IF;
 SELECT o.id,r.invoice_ref,t.cashier_stage,r.invoiced_at
 INTO v_id,v_existing,v_stage,v_invoiced
 FROM public.ff_orders o JOIN public.ff49_cashier_receipts r ON r.order_id=o.id
 JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
 WHERE o.branch_id=p_branch AND o.order_number=p_number::bigint FOR UPDATE OF r;
 IF NOT FOUND THEN RAISE EXCEPTION 'لا يوجد طلب موثق بهذا الرقم ضمن الفرع'; END IF;
 IF NOT public.ff_is_manager() AND NOT ff_private.a10_cashier_order_visible(v_id) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF v_invoiced IS NULL OR v_stage NOT IN ('printed','preparing','ready','handed_over') THEN
  RAISE EXCEPTION 'يجب إصدار الفاتورة في MicroPOS أولًا';
 END IF;
 IF NULLIF(pg_catalog.btrim(COALESCE(v_existing,'')),'') IS NOT NULL THEN
  IF pg_catalog.btrim(v_existing)=v_ref THEN RETURN pg_catalog.jsonb_build_object('documented',true,'already_documented',true,'order_id',v_id); END IF;
  RAISE EXCEPTION 'هذا الطلب موثق بمرجع مختلف؛ يُراجع المدير قبل التصحيح';
 END IF;
 UPDATE public.ff49_cashier_receipts SET invoice_ref=v_ref WHERE order_id=v_id;
 INSERT INTO public.ff_audit_log(actor_id,action,entity_type,entity_id,details)
 VALUES(auth.uid(),'ff27_document_invoice','order',v_id::text,pg_catalog.jsonb_build_object('invoice_ref',v_ref,'branch_id',p_branch));
 RETURN pg_catalog.jsonb_build_object('documented',true,'already_documented',false,'order_id',v_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.ff38_cancel_unassigned_order(p_order uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                    DECLARE v_role text; v_order public.ff_orders%ROWTYPE;
                                                                                                                                                                                                                                                                    BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                     SELECT p.role INTO v_role FROM public.ff_profiles p
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       WHERE p.user_id=auth.uid() AND p.active=true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          IF v_role IS NULL OR NOT public.ff38_permission_allowed(auth.uid(),'cancel_order') THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               RAISE EXCEPTION 'لا تملك صلاحية إلغاء الطلبات' USING ERRCODE='42501';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            IF p_order IS NULL OR length(pg_catalog.btrim(coalesce(p_reason,''))) NOT BETWEEN 1 AND 500 THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     RAISE EXCEPTION 'سبب الإلغاء مطلوب (حتى 500 حرف)';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          SELECT * INTO v_order FROM public.ff_orders WHERE id=p_order FOR UPDATE;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      IF NOT FOUND THEN RAISE EXCEPTION 'الطلب غير موجود'; END IF;
 IF NOT public.ff49_can_work_branch(v_order.branch_id,ARRAY[v_role]) THEN RAISE EXCEPTION 'الفرع غير مصرح' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   IF v_role='cashier' AND NOT ff_private.a10_cashier_order_visible(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF v_order.order_type <> 'delivery' OR v_order.status IN ('delivered','cancelled','reservation_completed') THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  RAISE EXCEPTION 'حالة الطلب لا تسمح بالإلغاء';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   IF EXISTS(SELECT 1 FROM public.ff38_delivery_tasks t WHERE t.order_id=p_order) THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      RAISE EXCEPTION 'لا يمكن إلغاء طلب قبله الموصل من هذه الشاشة';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               IF EXISTS(SELECT 1 FROM public.ff38_order_additions a WHERE a.order_id=p_order AND a.status <> 'cancelled') THEN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      RAISE EXCEPTION 'لا يمكن إلغاء طلب يحتوي على إضافات غير ملغاة';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       -- Expire only currently offered dispatches, without deleting history.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 UPDATE public.ff38_dispatch_offers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            SET status='expired',responded_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WHERE order_id=p_order AND status='offered';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     UPDATE public.ff_orders
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   SET status='cancelled',cancel_reason=pg_catalog.btrim(p_reason),updated_at=now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WHERE id=p_order;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  INSERT INTO public.ff38_order_cancellation_audit(order_id,actor_id,reason)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   VALUES(p_order,auth.uid(),pg_catalog.btrim(p_reason));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     INSERT INTO public.ff_order_events(order_id,old_status,new_status,note,actor_id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        VALUES(p_order,v_order.status,'cancelled',pg_catalog.left('إلغاء: '||pg_catalog.btrim(p_reason),2000),auth.uid());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            RETURN pg_catalog.jsonb_build_object('order_id',p_order,'status','cancelled');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                END $function$;

CREATE OR REPLACE FUNCTION public.ff38_dispatch(p_order uuid, p_driver uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_role text; v_branch uuid;
begin
 select role into v_role from public.ff_profiles where user_id=auth.uid() and active;
 if v_role is null or not public.ff38_permission_allowed(auth.uid(),'assign_driver') then
  raise exception 'لا تملك صلاحية توزيع الطلبات' using errcode='42501';
 end if;
 if p_order is null then raise exception 'الطلب غير متاح لصلاحيات حسابك' using errcode='42501'; end if;
 -- Acquire the same order lock first as the internal dispatcher.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('ff38-o-'||p_order::text));
 select branch_id into v_branch from public.ff_orders where id=p_order for update;
 if v_branch is null or not public.ff49_can_work_branch(v_branch,array[v_role]) then
  raise exception 'الطلب غير متاح لصلاحيات حسابك' using errcode='42501';
 end if;
 IF v_role='cashier' AND NOT ff_private.a10_cashier_order_visible(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 return public.ff38__offer_next(p_order,p_driver);
end $function$;

CREATE OR REPLACE FUNCTION public.ff50_change_request(p_order uuid, p_items jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                              DECLARE v_branch uuid;v_phase text;v_stage text;v_status text;v_role text;v_old_items jsonb;v_old_amount numeric;
                               v_new_amount numeric;v_n int;v_id uuid;
                               BEGIN
                                SELECT role INTO v_role FROM public.ff_profiles WHERE user_id=auth.uid() AND active;
 IF v_role IS NULL OR NOT public.ff38_permission_allowed(auth.uid(),'edit_order')
                                 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 5 AND 500
                                  OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
                                    RAISE EXCEPTION 'صلاحية التعديل والسبب والأصناف الصحيحة مطلوبة' USING ERRCODE='42501'; END IF;
 IF jsonb_array_length(p_items) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'الأصناف غير صالحة' USING ERRCODE='22023'; END IF;
                                     -- A row lock and a partial unique index prevent parallel edits.
                                      SELECT o.branch_id,o.items_total,t.phase,t.cashier_stage,o.status
                                       INTO v_branch,v_old_amount,v_phase,v_stage,v_status
                                        FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                                         WHERE o.id=p_order FOR UPDATE OF o,t;
                                          IF NOT FOUND OR v_phase<>'assigned' OR v_stage='handed_over' OR v_status IN ('cancelled','canceled','delivered','closed','reservation_completed') THEN
                                            RAISE EXCEPTION 'لا يمكن تعديل طلب غادر مع الموصل أو لم يتم إسناده'; END IF;
 IF NOT public.ff49_can_work_branch(v_branch,ARRAY[v_role]) THEN RAISE EXCEPTION 'الفرع غير مصرح' USING ERRCODE='42501'; END IF;
                                             IF v_role='cashier' AND NOT ff_private.a10_cashier_order_visible(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 IF EXISTS (SELECT 1 FROM public.ff38_order_additions WHERE order_id=p_order AND status='pending') THEN
                                               RAISE EXCEPTION 'توجد إضافة معلقة؛ يجب إنهاؤها أولًا'; END IF;
                                                SELECT count(*)::int,coalesce(sum(qty*price),0) INTO v_n,v_new_amount
                                                 FROM jsonb_to_recordset(p_items) AS r(name text,qty numeric,price numeric)
                                                  WHERE length(btrim(coalesce(name,'')))>0 AND qty>0 AND price>=0
 AND qty::text NOT IN ('NaN','Infinity','-Infinity') AND price::text NOT IN ('NaN','Infinity','-Infinity')
 AND qty=round(qty,3) AND price=round(price,2) AND qty*price=round(qty*price,2);
                                                   IF v_n<>jsonb_array_length(p_items) THEN RAISE EXCEPTION 'الأصناف الجديدة تحتوي على قيم غير صالحة' USING ERRCODE='22023'; END IF;
                                                    SELECT coalesce(jsonb_agg(jsonb_build_object('name',item_name,'qty',quantity,'price',unit_price,'item_notes',item_notes)
                                                     ORDER BY item_name,quantity,unit_price,item_notes),'[]'::jsonb) INTO v_old_items FROM public.ff_order_items WHERE order_id=p_order;
                                                      INSERT INTO public.ff50_order_changes(order_id,old_items,new_items,old_total,new_total,reason,requested_by)
                                                       VALUES(p_order,v_old_items,p_items,v_old_amount,v_new_amount,btrim(p_reason),auth.uid()) RETURNING id INTO v_id;
                                                        INSERT INTO public.ff50_order_change_events(change_id,actor_id,new_status,note)
                                                         VALUES(v_id,auth.uid(),'requested','طلب تعديل بانتظار موافقة الكاشير');
                                                          RETURN jsonb_build_object('change_id',v_id,'status','requested','difference',v_new_amount-v_old_amount);
                                                          END $function$;

CREATE OR REPLACE FUNCTION public.ff50_change_service_confirm(p_change uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                         DECLARE v public.ff50_order_changes%ROWTYPE;v_branch uuid;v_role text;v_phase text;v_stage text;v_status text;
                                                                         BEGIN
                                                                          SELECT * INTO v FROM public.ff50_order_changes WHERE id=p_change FOR UPDATE;
                                                                           IF NOT FOUND OR v.status<>'approved' THEN RAISE EXCEPTION 'لم يوافق الكاشير على تعديل هذا الطلب'; END IF;
                                                                            SELECT role INTO v_role FROM public.ff_profiles WHERE user_id=auth.uid() AND active;
 IF v_role IS NULL OR NOT public.ff38_permission_allowed(auth.uid(),'edit_order') THEN
                                                                              RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501'; END IF;
 SELECT o.branch_id,t.phase,t.cashier_stage,o.status INTO v_branch,v_phase,v_stage,v_status FROM public.ff_orders o JOIN public.ff38_delivery_tasks t ON t.order_id=o.id WHERE o.id=v.order_id FOR UPDATE OF o,t;
 IF NOT FOUND OR v_phase IS DISTINCT FROM 'assigned' OR v_stage='handed_over' OR v_status IN ('cancelled','canceled','delivered','closed','reservation_completed') THEN RAISE EXCEPTION 'لا تعديل بعد خروج الموصل أو إغلاق الطلب'; END IF;
 IF NOT public.ff49_can_work_branch(v_branch,ARRAY[v_role]) THEN RAISE EXCEPTION 'الفرع غير مصرح' USING ERRCODE='42501'; END IF;
                                                                               IF v_role='cashier' AND NOT ff_private.a10_cashier_order_visible(v.order_id) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 UPDATE public.ff50_order_changes SET status='service_confirmed',confirmed_by=auth.uid(),confirmed_at=now()
                                                                                WHERE id=p_change;
                                                                                 INSERT INTO public.ff50_order_change_events(change_id,actor_id,old_status,new_status,note)
                                                                                  VALUES(p_change,auth.uid(),'approved','service_confirmed','اعتمدت خدمة العملاء المسودة');
                                                                                   RETURN jsonb_build_object('status','service_confirmed');
                                                                                   END $function$;

CREATE OR REPLACE FUNCTION public.ff60_list_workflow(p_order uuid, p_limit integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                                                                                                                    DECLARE v_branch uuid;v_role text;v_driver uuid;v_result jsonb;
                                                                                                                                                                                                                                                                                                                                                    BEGIN
                                                                                                                                                                                                                                                                                                                                                      SELECT role INTO v_role FROM public.ff_profiles WHERE user_id=auth.uid() AND active;
                                                                                                                                                                                                                                                                                                                                                        SELECT branch_id INTO v_branch FROM public.ff_orders WHERE id=p_order;
                                                                                                                                                                                                                                                                                                                                                          IF v_role IS NULL OR v_branch IS NULL OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 120 THEN
                                                                                                                                                                                                                                                                                                                                                              RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501';
                                                                                                                                                                                                                                                                                                                                                                END IF;
                                                                                                                                                                                                                                                                                                                                                                  IF v_role='driver' THEN
                                                                                                                                                                                                                                                                                                                                                                      SELECT driver_id INTO v_driver FROM public.ff38_driver_links WHERE user_id=auth.uid();
                                                                                                                                                                                                                                                                                                                                                                        END IF;
                                                                                                                                                                                                                                                                                                                                                                          IF NOT (
                                                                                                                                                                                                                                                                                                                                                                              v_role IN ('manager','customer_service')
                                                                                                                                                                                                                                                                                                                                                                                  OR (v_role IN ('cashier','supervisor') AND EXISTS (
                                                                                                                                                                                                                                                                                                                                                                                          SELECT 1 FROM public.ff_user_branches WHERE user_id=auth.uid() AND branch_id=v_branch))
                                                                                                                                                                                                                                                                                                                                                                                              OR (v_role='driver' AND v_driver IS NOT NULL AND (
                                                                                                                                                                                                                                                                                                                                                                                                     EXISTS (SELECT 1 FROM public.ff38_delivery_tasks WHERE order_id=p_order AND driver_id=v_driver)
                                                                                                                                                                                                                                                                                                                                                                                                            OR EXISTS (SELECT 1 FROM public.ff38_dispatch_offers WHERE order_id=p_order AND driver_id=v_driver)
                                                                                                                                                                                                                                                                                                                                                                                                                ))
                                                                                                                                                                                                                                                                                                                                                                                                                  ) THEN RAISE EXCEPTION 'ليس لديك صلاحية مشاهدة سجل هذا الطلب' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                                                                                                                                                                                    IF v_role='cashier' AND EXISTS(SELECT FROM public.ff_orders o WHERE o.id=p_order AND o.order_type='delivery') AND NOT ff_private.a10_cashier_order_visible(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501';END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC,x.id DESC),'[]'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                        INTO v_result FROM (
                                                                                                                                                                                                                                                                                                                                                                                                                              SELECT id,event_type,from_value,to_value,driver_id,actor_id,created_at,details
                                                                                                                                                                                                                                                                                                                                                                                                                                    FROM public.ff60_workflow_events WHERE order_id=p_order
                                                                                                                                                                                                                                                                                                                                                                                                                                          ORDER BY created_at DESC,id DESC LIMIT p_limit
                                                                                                                                                                                                                                                                                                                                                                                                                                              ) x;
                                                                                                                                                                                                                                                                                                                                                                                                                                                RETURN v_result;
                                                                                                                                                                                                                                                                                                                                                                                                                                                END $function$;

CREATE OR REPLACE FUNCTION public.ff60_operational_queue(p_branch uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 150)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_role text;v_driver uuid;v_result jsonb;
BEGIN
  SELECT role INTO v_role FROM public.ff_profiles WHERE user_id=auth.uid() AND active;
    IF v_role IS NULL THEN RAISE EXCEPTION 'سجل الدخول بحساب نشط' USING ERRCODE='42501'; END IF;
      IF p_limit IS NULL OR p_limit<1 OR p_limit>200 THEN RAISE EXCEPTION 'حد النتائج بين 1 و200'; END IF;
        IF v_role='driver' THEN
            SELECT driver_id INTO v_driver FROM public.ff38_driver_links WHERE user_id=auth.uid();
              END IF;
                SELECT COALESCE(jsonb_agg(to_jsonb(q) ORDER BY q.created_at DESC),'[]'::jsonb) INTO v_result
                  FROM (
                      SELECT o.id, o.order_number, o.branch_id, o.area_snapshot AS area,
                                 o.status, o.created_at, o.order_type,
                                            t.driver_id, t.phase, t.cashier_stage, t.assigned_at, t.picked_up_at,
                                                       t.arrived_at, t.delivered_at,
                                                                  d.name AS driver_name,
                                                                             f.id AS offer_id, f.driver_id AS offer_driver_id, f.expires_at AS offer_expires_at,
                                                                                        (SELECT count(*) FROM public.ff38_order_additions a
                                                                                                      WHERE a.order_id=o.id AND a.status='pending')::int AS pending_additions,
                                                                                                                 (SELECT count(*) FROM public.ff49_driver_transfers x
                                                                                                                               WHERE x.order_id=o.id AND x.status='pending_cashier')::int AS pending_transfer,
                                                                                                                                          (SELECT count(*) FROM public.ff52_late_addition_consent c
                                                                                                                                                         JOIN public.ff38_order_additions a ON a.id=c.addition_id
                                                                                                                                                                       WHERE a.order_id=o.id AND c.state IN ('awaiting_driver','driver_accepted','invoiced'))::int AS pending_late_pickup,
                                                                                                                                                                                  (r.order_id IS NOT NULL) AS cashier_received,
                                                                                                                                                                                             CASE WHEN v_role='driver' THEN NULL ELSE r.invoice_ref END AS invoice_ref
                                                                                                                                                                                                 FROM public.ff_orders o
                                                                                                                                                                                                     LEFT JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                                                                                                                                                                                                         LEFT JOIN public.ff_drivers d ON d.id=t.driver_id
                                                                                                                                                                                                             LEFT JOIN public.ff49_cashier_receipts r ON r.order_id=o.id
                                                                                                                                                                                                                 LEFT JOIN LATERAL (
                                                                                                                                                                                                                       SELECT offer.id,offer.driver_id,offer.expires_at FROM public.ff38_dispatch_offers offer
                                                                                                                                                                                                                             WHERE offer.order_id=o.id AND offer.status='offered' AND offer.expires_at>now()
                                                                                                                                                                                                                                   ORDER BY offer.offered_at DESC LIMIT 1
                                                                                                                                                                                                                                       ) f ON true
                                                                                                                                                                                                                                           WHERE o.order_type='delivery'
                                                                                                                                                                                                                                                 AND (o.status NOT IN ('cancelled','delivered','reservation_completed')
                                                                                                                                                                                                                                                            OR o.created_at>now()-interval '24 hours')
                                                                                                                                                                                                                                                                  AND (p_branch IS NULL OR o.branch_id=p_branch)
                                                                                                                                                                                                                                                                        AND (
                                                                                                                                                                                                                                                                                v_role IN ('manager','customer_service')
                                                                                                                                                                                                                                                                                        OR (v_role IN ('cashier','supervisor') AND EXISTS (
                                                                                                                                                                                                                                                                                                     SELECT 1 FROM public.ff_user_branches b
                                                                                                                                                                                                                                                                                                                  WHERE b.user_id=auth.uid() AND b.branch_id=o.branch_id))
                                                                                                                                                                                                                                                                                                                          OR (v_role='driver' AND v_driver IS NOT NULL
                                                                                                                                                                                                                                                                                                                                      AND (t.driver_id=v_driver OR f.driver_id=v_driver))
                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                AND (v_role<>'cashier' OR ff_private.a10_cashier_order_visible(o.id))
 ORDER BY o.created_at DESC LIMIT p_limit
                                                                                                                                                                                                                                                                                                                                                  ) q;
                                                                                                                                                                                                                                                                                                                                                    RETURN v_result;
                                                                                                                                                                                                                                                                                                                                                    END $function$;

CREATE OR REPLACE FUNCTION public.ff_luxe_ack_cashier_cancel(p_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_branch uuid;
BEGIN
 SELECT branch_id INTO v_branch FROM public.ff_luxe_cancel_ack WHERE order_id=p_order FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'إلغاء الطلب غير موجود'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.ff_profiles p WHERE p.user_id=auth.uid() AND p.active AND (p.role='manager' OR (p.role='cashier' AND EXISTS(SELECT 1 FROM public.ff_user_branches ub WHERE ub.user_id=auth.uid() AND ub.branch_id=v_branch)))) THEN RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501'; END IF;
 IF NOT public.ff_is_manager() AND NOT ff_private.a10_cashier_order_visible(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 UPDATE public.ff_luxe_cancel_ack SET acknowledged_by=coalesce(acknowledged_by,auth.uid()),acknowledged_at=coalesce(acknowledged_at,now()) WHERE order_id=p_order;
 RETURN jsonb_build_object('acknowledged',true);
END;$function$;

CREATE OR REPLACE FUNCTION public.ff_luxe_cancel_assigned(p_order uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_order public.ff_orders%rowtype;v_phase text;v_driver uuid;v_role text;
begin
 if auth.uid() is null or not public.ff38_permission_allowed(auth.uid(),'cancel_order') then
  raise exception 'لا تملك صلاحية إلغاء الطلبات' using errcode='42501';
 end if;
 if length(btrim(coalesce(p_reason,''))) not between 1 and 500 then raise exception 'سبب الإلغاء مطلوب';end if;
 select role into v_role from public.ff_profiles where user_id=auth.uid() and active;
 if v_role not in ('manager','customer_service','supervisor','cashier') then raise exception 'الدور غير مخول بالإلغاء' using errcode='42501';end if;
 select * into v_order from public.ff_orders where id=p_order for update;
 if not found then raise exception 'الطلب غير موجود';end if;
 if v_role not in ('manager','customer_service') and not exists(
   select 1 from public.ff_user_branches b where b.user_id=auth.uid() and b.branch_id=v_order.branch_id
 ) then raise exception 'الفرع غير مصرح' using errcode='42501';end if;
 IF v_role='cashier' AND NOT ff_private.a10_cashier_order_visible(p_order) THEN RAISE EXCEPTION 'الطلب غير متاح لهذه الوجهة' USING ERRCODE='42501'; END IF;
 if v_order.status in ('cancelled','delivered','reservation_completed')
    or v_order.order_type is distinct from 'delivery'
 then raise exception 'حالة الطلب لا تسمح بالإلغاء';end if;
 select phase,driver_id into v_phase,v_driver from public.ff38_delivery_tasks where order_id=p_order for update;
 if v_phase is null then raise exception 'استخدم إلغاء الطلب قبل الإسناد';end if;
 if v_phase='delivered' then raise exception 'لا يمكن إلغاء طلب تم تسليمه للعميل';end if;
 update public.ff_orders set status='cancelled',cancel_reason=btrim(p_reason),updated_at=now() where id=p_order;
 update public.ff38_delivery_tasks set delivered_at=coalesce(delivered_at,now()),updated_at=now() where order_id=p_order;
 update public.ff38_dispatch_offers set status='expired',responded_at=now() where order_id=p_order and status='offered';
 insert into public.ff38_order_cancellation_audit(order_id,actor_id,reason) values(p_order,auth.uid(),btrim(p_reason));
 insert into public.ff_luxe_cancel_ack(order_id,branch_id,cancelled_by,reason)
 values(p_order,v_order.branch_id,auth.uid(),btrim(p_reason))
 on conflict(order_id) do nothing;
 if v_driver is not null then
  update public.ff38_driver_presence p set
   state='ready',updated_at=now(),last_seen_at=now()
  where p.driver_id=v_driver and p.state='busy'
   and not exists(select 1 from public.ff38_delivery_tasks t where t.driver_id=v_driver and t.delivered_at is null)
   and not exists(select 1 from public.ff38_dispatch_offers f where f.driver_id=v_driver and f.status='offered' and f.expires_at>now());
 end if;
 return jsonb_build_object('cancelled',true,'order_number',v_order.order_number,
  'cashier_ack_required',true,'driver_released',v_driver is not null);
end;$function$;
